import sqlite3
import sys
import re

def parse_filters(filters):
    parsed = []
    for filter_str in filters:
        # Split into column and operator+value
        match = re.match(r'^([a-zA-Z]+)([<>!=]=?)([^=]+)$', filter_str)
        if not match:
            continue  # Skip invalid filters
        column, operator, value = match.groups()
        parsed.append((column, operator, value))
    return parsed

def build_sql(parsed_filters):
    conditions = []
    for column, operator, value in parsed_filters:
        if column == 'id':
            operator = '=' if operator == '=' else f'>{operator}'
        elif column == 'level':
            operator = '=' if operator == '=' else f'>{operator}'
        else:
            operator = operator
        conditions.append(f"{column} {operator} ?")
    if not conditions:
        return "SELECT * FROM events ORDER BY id ASC"
    return f"SELECT * FROM events WHERE {' AND '.join(conditions)} ORDER BY id ASC"

def main():
    if len(sys.argv) < 2:
        print("Usage: python event_query.py <db_path> <filter> [<filter> ...]")
        sys.exit(1)

    db_path = sys.argv[1]
    filters = sys.argv[2:]

    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
    except sqlite3.Error as e:
        print(f"Database error: {e}")
        sys.exit(1)

    parsed_filters = parse_filters(filters)
    if not parsed_filters:
        print("No valid filters provided")
        sys.exit(0)

    sql = build_sql(parsed_filters)
    cursor.execute(sql)

    rows = cursor.fetchall()
    if not rows:
        sys.exit(0)

    for row in rows:
        print(f"{row[0]}|{row[1]}|{row[2]}|{row[3]}|{row[4]}")

    conn.close()

if __name__ == "__main__":
    main()

import sqlite3
import sys
import re

def parse_filter(filter_str):
    operator_match = re.match(r'^([a-zA-Z]+)([<>]=?)$', filter_str)
    if not operator_match:
        raise ValueError("Invalid filter format")
    column = operator_match.group(1)
    op = operator_match.group(2)
    value = filter_str[len(column):]
    return column, op, value

