import sys
import sqlite3
from collections import defaultdict

def parse_filter(filter_str):
    parts = filter_str.split('=')
    if len(parts) != 2:
        return None
    column, value = parts
    return column.strip(), value.strip()

def main():
    if len(sys.argv) != 3:
        print("Usage: python event_query.py <database_path> <filter_string>")
        return

    db_path, filter_str = sys.argv[1], sys.argv[2]
    column, value = parse_filter(filter_str)

    if column not in ['id', 'category', 'level', 'message', 'created_at']:
        print("Invalid column specified in filter.")
        return

    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()

        # Build the WHERE clause dynamically
        where_clause = f"{column} = ?"
        cursor.execute(f"SELECT id, category, level, message, created_at FROM events WHERE {where_clause}", (value,))

        # Fetch all matching rows
        rows = cursor.fetchall()

        # Format and print each row
        for row in rows:
            print(f"{row[0]}|{row[1]}|{row[2]}|{row[3]}|{row[4]}")

    except sqlite3.Error as e:
        print(f"Database error: {e}")
    finally:
        if 'conn' in locals():
            conn.close()

if __name__ == "__main__":
    main()
